import React, { useState } from 'react';

function Contact() {
  const [status, setStatus] = useState({
    type: 'idle',
    message: '',
  });

  const handleSubmit = async (event) => {
    event.preventDefault();

    setStatus({
      type: 'loading',
      message: 'Enviando mensagem...',
    });

    const form = event.currentTarget;
    const formData = new FormData(form);

    formData.append('_subject', 'Novo contato pelo portfolio');
    formData.append('_template', 'table');

    if (typeof window !== 'undefined') {
      formData.append('_url', window.location.href);
    }

    try {
      const response = await fetch(
        'https://formsubmit.co/ajax/rafaelcamachofitti15@gmail.com',
        {
          method: 'POST',
          headers: {
            Accept: 'application/json',
          },
          body: formData,
        }
      );

      const result = await response.json();

      if (!response.ok || result.success === false) {
        throw new Error(result.message || 'Falha no envio.');
      }

      setStatus({
        type: 'success',
        message: 'Mensagem enviada com sucesso. Vou retornar em breve.',
      });
      form.reset();
    } catch (error) {
      setStatus({
        type: 'error',
        message: 'Nao foi possivel enviar agora. Tente novamente em instantes.',
      });
    }
  };

  return (
    <section id="contact" className="section">
      <div className="container">
        <div className="section__heading">
          <span className="eyebrow">Contato</span>
          <h2>Se você quer construir algo forte, vamos conversar.</h2>
          <p>
            Estou aberto a oportunidades em produto, engenharia de software e
            projetos em que performance, escala e boa experiência importem.
          </p>
        </div>
        <div className="contact__grid">
          <div className="glass card contact__panel">
            <div className="contact__info">
              <p>
                <strong>Email</strong>
                <a href="mailto:rafaelcamachofitti15@gmail.com">
                  rafaelcamachofitti15@gmail.com
                </a>
              </p>
              <p>
                <strong>Telefone</strong>
                <a href="tel:+5531984440770">(31) 98444-0770</a>
              </p>
              <p>
                <strong>Base</strong>
                <span>Belo Horizonte, MG, Brasil</span>
              </p>
            </div>
          </div>
          <div className="glass card contact">
            <form onSubmit={handleSubmit} className="contact__form">
              <div className="form__group">
                <label htmlFor="nome">Nome</label>
                <input
                  type="text"
                  id="nome"
                  name="name"
                  placeholder="Seu nome"
                  required
                />
              </div>
              <div className="form__group">
                <label htmlFor="email">Email</label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  placeholder="seu@email.com"
                  required
                />
              </div>
              <div className="form__group">
                <label htmlFor="mensagem">Mensagem</label>
                <textarea
                  id="mensagem"
                  name="message"
                  rows="5"
                  placeholder="Conte rapidamente sobre a oportunidade ou projeto"
                  required
                ></textarea>
              </div>
              <input
                type="text"
                name="_honey"
                className="contact__honeypot"
                tabIndex="-1"
                autoComplete="off"
              />
              <button
                type="submit"
                className="btn"
                disabled={status.type === 'loading'}
              >
                {status.type === 'loading' ? 'Enviando...' : 'Enviar mensagem'}
              </button>
              {status.type !== 'idle' && (
                <p className={`contact__status contact__status--${status.type}`}>
                  {status.message}
                </p>
              )}
            </form>
          </div>
        </div>
      </div>
    </section>
  );
}

export default Contact;
